from fastapi import APIRouter, Depends, HTTPException
import ray

router = APIRouter(prefix="/inference/jobs")

@router.get("/{object_ref_hex}/result")
async def get_ray_batch_inference_result(
    object_ref_hex: str,
    job_store: RayJobMetadataStore = Depends(get_ray_job_store),
    current_user: User = Depends(get_current_user)
):
    job_meta = await job_store.get_job_by_ref(object_ref_hex)
    if not job_meta or job_meta.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=404, detail="Inference job not found")

    try:
        obj_ref = ray.ObjectRef.from_hex(object_ref_hex)
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid Ray ObjectRef format")

    ready, unready = ray.wait([obj_ref], timeout=0.1)
    if not ready:
        return {"status": "PENDING", "object_ref": object_ref_hex}

    output = ray.get(obj_ref)
    return {"status": "SUCCESS", "object_ref": object_ref_hex, "output": output}
